// Package consentpage holds the stylesheet, brand fonts and Speakeasy wordmark
// shared by the server-rendered authorization pages: the MCP consent page, the
// Platform MCP OAuth page and the shared authorization error page. The stylesheet is generated by
// `aube run -F dashboard build:consent-page` from client/dashboard/src/consent-page;
// never hand-edit the assets. The build compiles the dashboard design system
// against those pages' templates, so they use the same tokens, type scale and
// utilities as the dashboard rather than a parallel hand-written stylesheet
// that drifts.
package consentpage

import (
	"embed"
	"fmt"
	"html/template"
	"io/fs"
	"path"
	"strings"
)

//go:embed assets
var assets embed.FS

// LogoTemplate defines the "speakeasyWordmark" template. Parse it into a
// page template to render the mark. Kept in its own file because it is
// generated from the dashboard's GramLogo component and is almost entirely
// path data.
//
//go:embed logo.html
var LogoTemplate string

// Styles is the compiled stylesheet, inlined into a page's <style> block.
// Inlined rather than linked because the pages are served Cache-Control:
// no-store, so a separate request would buy no caching and only add a
// round-trip before first paint. template.CSS because the content is a build
// artifact, not user input.
var Styles = func() template.CSS {
	data, err := assets.ReadFile("assets/consent-page.css")
	if err != nil {
		panic(fmt.Sprintf("read embedded consent page stylesheet: %v", err))
	}
	// #nosec G203 -- the stylesheet is a build artifact compiled from the
	// dashboard design system and embedded at compile time; no request data
	// reaches it.
	return template.CSS(data)
}()

// Font returns one embedded brand font by file name. ok is false for any name
// that is not a plain .woff2 file name in the embedded directory.
func Font(name string) (data []byte, ok bool) {
	// The name indexes a fixed embedded directory, so reject anything that
	// could escape it rather than relying on the FS to refuse.
	if name == "" || !strings.HasSuffix(name, ".woff2") || name != path.Base(name) {
		return nil, false
	}
	data, err := assets.ReadFile("assets/" + name)
	if err != nil {
		return nil, false
	}
	return data, true
}

// FontNames lists the embedded font files.
func FontNames() ([]string, error) {
	entries, err := fs.ReadDir(assets, "assets")
	if err != nil {
		return nil, fmt.Errorf("read embedded consent page assets: %w", err)
	}
	names := make([]string, 0, len(entries))
	for _, e := range entries {
		if strings.HasSuffix(e.Name(), ".woff2") {
			names = append(names, e.Name())
		}
	}
	return names, nil
}
